def countHoles(pic):
	h = 0
	for i in range(1, len(pic) - 1):
		for j in range(1, len(pic[i]) - 1):
			h += pic[i + 1][j] == pic[i - 1][j] == pic[i][j - 1] == pic[i][j + 1] and pic[i + 1][j] != pic[i][j]
	return h

